@php($business = $quotation->business_snapshot ?? [])
<x-layouts.pdf :business="$business"><div class="header"><span class="brand">{{ $business['business_name'] ?? 'CashFlow' }}</span><span class="title">QUOTATION</span><p>{{ $business['business_address'] ?? '' }}<br>{{ $business['business_email'] ?? '' }} {{ $business['business_phone'] ?? '' }}</p></div><table class="grid"><tr><td><strong>Bill To</strong><br>{{ $quotation->client->name }}<br>{{ $quotation->client->company }}<br>{{ $quotation->client->address }}<br>{{ $quotation->client->email }}</td><td><strong>{{ $quotation->quotation_number }}</strong><br>Issue: {{ $quotation->issue_date->format('d M Y') }}<br>Valid Until: {{ $quotation->valid_until->format('d M Y') }}</td></tr></table><h2>{{ $quotation->project_title }}</h2><table class="items"><thead><tr><th>#</th><th>Description</th><th>Type</th><th>Qty/Hours</th><th>Unit Price</th><th>Amount</th></tr></thead><tbody>@foreach($quotation->items as $item)<tr><td>{{ $loop->iteration }}</td><td>{{ $item->description }}</td><td>{{ ucfirst($item->item_type) }}</td><td>{{ $item->quantity }}</td><td>{{ $quotation->currency }} {{ number_format($item->unit_price, 2) }}</td><td>{{ $quotation->currency }} {{ number_format($item->amount, 2) }}</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>Subtotal</td><td>{{ $quotation->currency }} {{ number_format($quotation->subtotal, 2) }}</td></tr><tr><td>Discount</td><td>{{ $quotation->currency }} {{ number_format($quotation->discount_amount, 2) }}</td></tr><tr><td>Tax</td><td>{{ $quotation->currency }} {{ number_format($quotation->tax_amount, 2) }}</td></tr><tr class="total"><td>Total</td><td>{{ $quotation->currency }} {{ number_format($quotation->total, 2) }}</td></tr></table>@if($quotation->notes)<div class="box"><strong>Notes</strong><br>{{ $quotation->notes }}</div>@endif @if($quotation->payment_terms)<div class="box"><strong>Payment Terms</strong><br>{{ $quotation->payment_terms }}</div>@endif </x-layouts.pdf>
